1	/**
2	 * @module features/tv-dashboard/model/tvMath
3	 *
4	 * Funções PURAS do Dashboard de Crise (painel TV): pró-rata de meta,
5	 * delta semanal, classificação RAG, formatação compacta de moeda,
6	 * staleness e agregações determinísticas usadas pelo hook de dados.
7	 *
8	 * Tudo aqui é livre de I/O e testável em isolamento (`tvMath.test.ts`).
9	 */
10	
11	import type {
12	  TvBusinessHours,
13	  TvCriticalItem,
14	  TvDateRange,
15	  TvException,
16	  TvExceptionsResult,
17	  TvFreshness,
18	  TvFreshnessLevel,
19	  TvPeriod,
20	  TvRagStatus,
21	  TvRecentMove,
22	  TvStockAlertItem,
23	  TvStoreWeeklyGoal,
24	  TvWeekSegment,
25	  TvWeeklyGoal,
26	} from './types';
27	
28	// ─────────────────────────────────────────────────────────────────────────────
29	// Constantes de negócio
30	// ─────────────────────────────────────────────────────────────────────────────
31	
32	/**
33	 * Janela do DIA COMERCIAL das lojas usada no pró-rata da meta (hora local):
34	 * 08:00–23:00 — lojas abrem às 8h (brunch Lago Sul) e o dia comercial fecha
35	 * às 23h (regra do CTO 2026-06-12; supersede o 10–22 do design.md §1.6
36	 * regra 5). AJUSTÁVEL: se o horário comercial mudar, basta alterar aqui —
37	 * pró-rata, "sem movimentação" e a virada do dia ({@link businessTodayIso})
38	 * derivam daqui.
39	 */
40	export const TV_BUSINESS_HOURS: TvBusinessHours = { start: 8, end: 23 };
41	
42	/**
43	 * Janela de produção da FÁBRICA (design.md §1.6 regra 5 + §5: 06:00–18:00).
44	 * Usada TANTO no RAG da fábrica quanto no alerta visual do card.
45	 */
46	export const TV_FACTORY_HOURS: TvBusinessHours = { start: 6, end: 18 };
47	
48	/** Horas sem movimentação (dentro da janela) que tornam a LOJA âmbar. */
49	export const NO_MOVEMENT_THRESHOLD_HOURS = 3;
50	
51	/** Horas sem bipagem (na janela de produção) que tornam a FÁBRICA âmbar (§5). */
52	export const FACTORY_NO_MOVEMENT_THRESHOLD_HOURS = 2;
53	
54	/**
55	 * Ratio pró-rata (%real / %esperado, em %) abaixo do qual a venda live fica
56	 * ÂMBAR — nunca vermelho (design.md §1.6 regra 6: ratio menor que 0,75).
57	 */
58	export const LIVE_SALES_AMBER_THRESHOLD_PCT = 75;
59	
60	/** Hora local a partir da qual a regra de venda fraca passa a valer (§1.6). */
61	export const LIVE_SALES_AMBER_FROM_HOUR = 11;
62	
63	/** Máximo de linhas exibidas na faixa de exceções. */
64	export const TV_EXCEPTIONS_LIMIT = 7;
65	
66	/**
67	 * Minutos sem atualização do flash, dentro do horário comercial e com caixa
68	 * aberto, que caracterizam PDV dessincronizado — acima da cadência normal
69	 * ~1h do Degust (RCA Asa Norte 2026-06-19).
70	 */
71	export const TV_FLASH_STALE_MINUTES = 90;
72	
73	/** Itens do mini-feed "AGORA" por coluna de unidade. */
74	export const TV_MINI_FEED_SIZE = 3;
75	
76	/** Itens de estoque crítico exibidos na coluna (lista completa no drill-down). */
77	export const TV_CRITICAL_TOP_N = 5;
78	
79	/** Máximo de linhas do feed de movimentações no drill-down por loja. */
80	export const TV_DETAIL_FEED_LIMIT = 50;
81	
82	/**
83	 * Setor canônico de `produtos_master.setor` cujos itens entram nos ALERTAS
84	 * de estoque crítico do painel (regra do CTO 2026-06-05: alertas só do setor
85	 * de produtos vendáveis — EMBALAGENS, INSUMOS, CÂMARA FRIA, ITENS COZINHA,
86	 * MERCEARIA, COMIDAS, PRODUTOS DE LIMPEZA etc. ficam FORA).
87	 *
88	 * Comparar SEMPRE por igualdade exata pós-{@link normalizeSetor} (nunca por
89	 * prefixo/ILIKE: existe o setor "PRODUTOS DE LIMPEZA") — use
90	 * {@link isTvAlertSetor}.
91	 */
92	export const TV_ALERT_SETOR = 'PRODUTOS';
93	
94	/**
95	 * ÚNICA loja cujo faturamento de PDV embute delivery (BSB Shopping): lá o
96	 * iFood/delivery passa pelo caixa Degust junto com o balcão, então o card
97	 * quebra "Loja × Delivery" (R1 da spec tv-acompanhamento-live). Nas demais
98	 * lojas o delivery NÃO entra no PDV — quebra não se aplica.
99	 *
100	 * É `lojas.id` interno (não código Degust). Constante nomeada de propósito:
101	 * exceção de NEGÓCIO documentada, não um hardcode espalhado.
102	 */
103	export const TV_DELIVERY_SPLIT_LOJA_ID = 6;
104	
105	// ─────────────────────────────────────────────────────────────────────────────
106	// Datas (helpers locais, sem dependência de timezone UTC)
107	// ─────────────────────────────────────────────────────────────────────────────
108	
109	/** Formata uma data como YYYY-MM-DD no fuso LOCAL (não UTC). */
110	export function toIsoDateLocal(d: Date): string {
111	  const y = d.getFullYear();
112	  const m = String(d.getMonth() + 1).padStart(2, '0');
113	  const day = String(d.getDate()).padStart(2, '0');
114	  return `${y}-${m}-${day}`;
115	}
116	
117	/** Faz parse de YYYY-MM-DD como data LOCAL (evita shift de fuso do `new Date(iso)`). */
118	export function parseIsoDateLocal(iso: string): Date {
119	  const [y, m, d] = iso.split('-').map(Number);
120	  return new Date(y, (m ?? 1) - 1, d ?? 1);
121	}
122	
123	/** Soma `days` dias a uma data, retornando nova instância. */
124	export function addDays(d: Date, days: number): Date {
125	  const out = new Date(d);
126	  out.setDate(out.getDate() + days);
127	  return out;
128	}
129	
130	/**
131	 * Dia COMERCIAL corrente do painel (YYYY-MM-DD local).
132	 *
133	 * O dia comercial vai de 08h a 23h ({@link TV_BUSINESS_HOURS}): a partir
134	 * das 23h o painel VIRA para o dia seguinte — tudo zera e o novo dia
135	 * começa — então `now` com hora ≥ 23 retorna AMANHÃ. Vendas de madrugada
136	 * (00h–05h) pertencem ao caixa do dia ANTERIOR (mesma convenção de
137	 * {@link TV_OVERNIGHT_END_HOUR}/{@link businessHourRank}): nesse horário o
138	 * dia comercial corrente é o próprio dia-calendário, ainda zerado até a
139	 * abertura das 08h — os totais do dia fechado ficam acessíveis no
140	 * histórico (◀).
141	 */
142	export function businessTodayIso(now: Date): string {
143	  return now.getHours() >= TV_BUSINESS_HOURS.end
144	    ? toIsoDateLocal(addDays(now, 1))
145	    : toIsoDateLocal(now);
146	}
147	
148	/** Rótulo de defasagem "até DD/MM" para dado que não é de hoje. */
149	export function formatLaggedDateLabel(isoDate: string): string {
150	  const d = parseIsoDateLocal(isoDate);
151	  const dd = String(d.getDate()).padStart(2, '0');
152	  const mm = String(d.getMonth() + 1).padStart(2, '0');
153	  return `até ${dd}/${mm}`;
154	}
155	
156	/**
157	 * Parser do timestamp pt-BR do Degust (`ultima_atualizacao` vem como
158	 * "DD/MM/YYYY HH:mm:ss"): `new Date()` interpreta como MM/DD e FALHA para
159	 * dia maior que 12. Faz parse como data LOCAL; aceita segundos opcionais e
160	 * cai pro parse nativo para outros formatos (ex.: ISO). Inválido → null.
161	 */
162	export function parseBrDateTime(value: string | null | undefined): Date | null {
163	  if (!value) return null;
164	  const m = value.match(
165	    /^(\d{2})\/(\d{2})\/(\d{4})[ T](\d{2}):(\d{2})(?::(\d{2}))?$/,
166	  );
167	  if (m) {
168	    const [, dd, mm, yyyy, hh, mi, ss] = m;
169	    const month = Number(mm);
170	    const day = Number(dd);
171	    if (month < 1 || month > 12 || day < 1 || day > 31) return null;
172	    return new Date(
173	      Number(yyyy),
174	      month - 1,
175	      day,
176	      Number(hh),
177	      Number(mi),
178	      ss ? Number(ss) : 0,
179	    );
180	  }
181	  const fallback = new Date(value);
182	  return Number.isNaN(fallback.getTime()) ? null : fallback;
183	}
184	
185	/**
186	 * Parser do `ultima_atualizacao` do flash-vendas Degust, cujo formato de
187	 * data DEPENDE da culture do servidor da API: historicamente chegava como
188	 * "DD/MM/YYYY HH:mm:ss" (pt-BR), mas em 2026-06-12 o payload real veio
189	 * "06/12/2026 13:17:00" — MM/DD/YYYY (en-US). Ler cegamente como DD/MM
190	 * jogava o flash pra 6/dez e o gate da virada do dia zerava TODOS os cards.
191	 *
192	 * Estratégia: gera as DUAS interpretações ("A/B" como dia/mês E como
193	 * mês/dia, descartando inválidas — mês 13, 31/02 etc.) e escolhe a que cai
194	 * na janela plausível [now−3d, now+1d]: flash é dado quase-live, nunca está
195	 * a semanas do relógio. As duas leituras distam ≥28 dias entre si, então no
196	 * máximo UMA cai na janela — exceto quando A === B (são idênticas). Se
197	 * nenhuma cair (dado muito stale), devolve a mais próxima de `now`: data
198	 * parseável porém velha é problema de FRESHNESS, não de parsing. Sem
199	 * leitura válida → null.
200	 */
201	export function parseDegustFlashDateTime(
202	  raw: string | null | undefined,
203	  now: Date,
204	): Date | null {
205	  if (!raw) return null;
206	  const m = raw.match(
207	    /^(\d{1,2})\/(\d{1,2})\/(\d{4})[ T](\d{1,2}):(\d{2})(?::(\d{2}))?$/,
208	  );
209	  if (!m) return null;
210	  const [, aStr, bStr, yyyy, hh, mi, ss] = m;
211	  const a = Number(aStr);
212	  const b = Number(bStr);
213	  const build = (day: number, month: number): Date | null => {
214	    if (month < 1 || month > 12 || day < 1 || day > 31) return null;
215	    const d = new Date(
216	      Number(yyyy),
217	      month - 1,
218	      day,
219	      Number(hh),
220	      Number(mi),
221	      ss ? Number(ss) : 0,
222	    );
223	    // Overflow de dia no mês (31/02 → vira 03/03) = leitura inválida
224	    if (d.getMonth() !== month - 1 || d.getDate() !== day) return null;
225	    return d;
226	  };
227	
228	  const candidates: Date[] = [];
229	  const asDdMm = build(a, b);
230	  if (asDdMm) candidates.push(asDdMm);
231	  if (a !== b) {
232	    const asMmDd = build(b, a);
233	    if (asMmDd) candidates.push(asMmDd);
234	  }
235	  if (candidates.length === 0) return null;
236	
237	  const DAY_MS = 86_400_000;
238	  const inWindow = candidates.filter(
239	    (d) =>
240	      d.getTime() >= now.getTime() - 3 * DAY_MS &&
241	      d.getTime() <= now.getTime() + DAY_MS,
242	  );
243	  const pool = inWindow.length > 0 ? inWindow : candidates;
244	  return pool.reduce((best, d) =>
245	    Math.abs(d.getTime() - now.getTime()) <
246	    Math.abs(best.getTime() - now.getTime())
247	      ? d
248	      : best,
249	  );
250	}
251	
252	/** Hora local "HH:mm" de um timestamp ISO ("—" para ausente/inválido). */
253	export function timeHHMMFromIso(iso: string | null | undefined): string {
254	  if (!iso) return '—';
255	  const d = new Date(iso);
256	  if (Number.isNaN(d.getTime())) return '—';
257	  const hh = String(d.getHours()).padStart(2, '0');
258	  const mm = String(d.getMinutes()).padStart(2, '0');
259	  return `${hh}:${mm}`;
260	}
261	
262	// ─────────────────────────────────────────────────────────────────────────────
263	// Ranges do filtro global de período (v3) — datas LOCAIS, puras e testáveis
264	// ─────────────────────────────────────────────────────────────────────────────
265	
266	/**
267	 * Range do filtro global (fechado [from, to], YYYY-MM-DD local):
268	 * - `today`: hoje → hoje;
269	 * - `week`: segunda-feira da semana corrente → hoje;
270	 * - `month`: dia 1º do mês corrente → hoje.
271	 */
272	export function periodRange(period: TvPeriod, now: Date): TvDateRange {
273	  const today = toIsoDateLocal(now);
274	  if (period === 'today') return { from: today, to: today };
275	  if (period === 'week') {
276	    // getDay(): 0=domingo → 0=segunda com (dow+6)%7
277	    const dowFromMonday = (now.getDay() + 6) % 7;
278	    const monday = addDays(now, -dowFromMonday);
279	    return { from: toIsoDateLocal(monday), to: today };
280	  }
281	  const firstOfMonth = new Date(now.getFullYear(), now.getMonth(), 1);
282	  return { from: toIsoDateLocal(firstOfMonth), to: today };
283	}
284	
285	/**
286	 * Período ANTERIOR equivalente para comparativos do filtro global:
287	 * - `today`: ontem → ontem;
288	 * - `week`: semana passada até o MESMO dia da semana (seg → hoje−7);
289	 * - `month`: mês passado do dia 1º até o MESMO dia do mês — clampado ao
290	 *   último dia quando o mês anterior é mais curto (31/05 → 30/04).
291	 */
292	export function previousPeriodRange(period: TvPeriod, now: Date): TvDateRange {
293	  if (period === 'today') {
294	    const yesterday = toIsoDateLocal(addDays(now, -1));
295	    return { from: yesterday, to: yesterday };
296	  }
297	  if (period === 'week') {
298	    const dowFromMonday = (now.getDay() + 6) % 7;
299	    const mondayLastWeek = addDays(now, -dowFromMonday - 7);
300	    return {
301	      from: toIsoDateLocal(mondayLastWeek),
302	      to: toIsoDateLocal(addDays(now, -7)),
303	    };
304	  }
305	  const y = now.getFullYear();
306	  const m = now.getMonth();
307	  const firstPrev = new Date(y, m - 1, 1);
308	  // `new Date(y, m, 0)` = último dia do mês ANTERIOR a `m`
309	  const lastDayPrevMonth = new Date(y, m, 0).getDate();
310	  const toPrev = new Date(y, m - 1, Math.min(now.getDate(), lastDayPrevMonth));
311	  return { from: toIsoDateLocal(firstPrev), to: toIsoDateLocal(toPrev) };
312	}
313	
314	/**
315	 * Range anterior de MESMA DURAÇÃO em dias, imediatamente antes do range
316	 * dado (drill-down com filtro custom: [from−N, from−1] para N dias).
317	 */
318	export function previousRangeSameDuration(range: TvDateRange): TvDateRange {
319	  const from = parseIsoDateLocal(range.from);
320	  const to = parseIsoDateLocal(range.to);
321	  // Math.round absorve a hora de DST (diferença 23h/25h em viradas de horário)
322	  const days = Math.round((to.getTime() - from.getTime()) / 86_400_000) + 1;
323	  return {
324	    from: toIsoDateLocal(addDays(from, -days)),
325	    to: toIsoDateLocal(addDays(to, -days)),
326	  };
327	}
328	
329	/**
330	 * Converte um range de DIAS locais em limites de TIMESTAMP para filtrar
331	 * colunas timestamptz (ex.: `perdas.data_identificacao`): início = 00:00
332	 * local do 1º dia (inclusive); fim = 00:00 local do dia SEGUINTE ao último
333	 * (exclusivo — usar `.lt`, nunca `.lte`).
334	 */
335	export function rangeToLocalDayBounds(range: TvDateRange): {
336	  startIso: string;
337	  endExclusiveIso: string;
338	} {
339	  const start = parseIsoDateLocal(range.from);
340	  const endExclusive = addDays(parseIsoDateLocal(range.to), 1);
341	  return {
342	    startIso: start.toISOString(),
343	    endExclusiveIso: endExclusive.toISOString(),
344	  };
345	}
346	
347	/**
348	 * Range do filtro global DESLOCADO `offset` períodos no tempo (R2 —
349	 * histórico navegável). Offset 0 = comportamento de {@link periodRange}
350	 * (período corrente, parcial até hoje). Offset −n = período PASSADO
351	 * COMPLETO n posições atrás:
352	 * - `today`: o dia inteiro n dias atrás;
353	 * - `week`: a semana seg-dom COMPLETA n semanas atrás;
354	 * - `month`: o mês-calendário COMPLETO n meses atrás.
355	 *
356	 * Offset positivo não é suportado (não há futuro a navegar) — tratado
357	 * como 0 por segurança.
358	 */
359	export function shiftedPeriodRange(
360	  period: TvPeriod,
361	  offset: number,
362	  now: Date,
363	): TvDateRange {
364	  if (offset >= 0) return periodRange(period, now);
365	  if (period === 'today') {
366	    const day = toIsoDateLocal(addDays(now, offset));
367	    return { from: day, to: day };
368	  }
369	  if (period === 'week') {
370	    const dowFromMonday = (now.getDay() + 6) % 7;
371	    const monday = addDays(now, -dowFromMonday + offset * 7);
372	    return { from: toIsoDateLocal(monday), to: toIsoDateLocal(addDays(monday, 6)) };
373	  }
374	  const first = new Date(now.getFullYear(), now.getMonth() + offset, 1);
375	  // `new Date(y, m+1, 0)` = último dia do mês `m`
376	  const last = new Date(now.getFullYear(), now.getMonth() + offset + 1, 0);
377	  return { from: toIsoDateLocal(first), to: toIsoDateLocal(last) };
378	}
379	
380	// ─────────────────────────────────────────────────────────────────────────────
381	// Meta mensal — semanas seg-dom recortadas ao mês + redistribuição (R4)
382	// ─────────────────────────────────────────────────────────────────────────────
383	
384	/**
385	 * Segmentos seg-dom de um mês, RECORTADOS aos limites do mês: o primeiro
386	 * e o último podem ter menos de 7 dias (mês que começa/termina no meio da
387	 * semana). `index` é 1-based ("Semana 1").
388	 *
389	 * @param year - Ano (ex.: 2026).
390	 * @param monthIndex0 - Mês 0-based (convenção JS `Date.getMonth()`).
391	 */
392	export function monthWeekSegments(
393	  year: number,
394	  monthIndex0: number,
395	): TvWeekSegment[] {
396	  const lastDay = new Date(year, monthIndex0 + 1, 0).getDate();
397	  const segments: TvWeekSegment[] = [];
398	  let day = 1;
399	  let index = 1;
400	  while (day <= lastDay) {
401	    const start = new Date(year, monthIndex0, day);
402	    const dowFromMonday = (start.getDay() + 6) % 7;
403	    const endDay = Math.min(day + (6 - dowFromMonday), lastDay);
404	    segments.push({
405	      index,
406	      from: toIsoDateLocal(start),
407	      to: toIsoDateLocal(new Date(year, monthIndex0, endDay)),
408	      days: endDay - day + 1,
409	    });
410	    day = endDay + 1;
411	    index += 1;
412	  }
413	  return segments;
414	}
415	
416	/**
417	 * Metas semanais do mês de `now` com REDISTRIBUIÇÃO iterativa da meta
418	 * mensal (que é fixa): para cada segmento, em ordem,
419	 * `target = (metaMensal − comprometido) × dias do segmento ÷ dias restantes`,
420	 * onde "comprometido" acumula o REALIZADO das semanas já encerradas e o
421	 * TARGET das semanas correntes/futuras (assume on-target dali em diante).
422	 *
423	 * Consequências (A4 da spec):
424	 * - semana que não bate a meta ⇒ targets das seguintes SOBEM;
425	 * - semana que supera ⇒ targets das seguintes DESCEM;
426	 * - invariante: realizado das semanas passadas + soma dos targets
427	 *   restantes = metaMensal, sempre (targets podem ficar negativos se o
428	 *   realizado já passou da meta — honesto, sem clamp).
429	 *
430	 * `achieved` = soma de `realizadoPorDia` nos dias do segmento (semanas
431	 * passadas e corrente); null para semanas futuras (sem dados ainda).
432	 */
433	export function weeklyTargets(
434	  metaMensal: number,
435	  realizadoPorDia: Map<string, number>,
436	  now: Date,
437	): TvWeeklyGoal[] {
438	  const segments = monthWeekSegments(now.getFullYear(), now.getMonth());
439	  const todayIso = toIsoDateLocal(now);
440	  const sumSegment = (seg: TvWeekSegment): number => {
441	    let sum = 0;
442	    let d = parseIsoDateLocal(seg.from);
443	    for (let i = 0; i < seg.days; i += 1) {
444	      sum += realizadoPorDia.get(toIsoDateLocal(d)) ?? 0;
445	      d = addDays(d, 1);
446	    }
447	    return sum;
448	  };
449	
450	  let committed = 0;
451	  let daysRemaining = segments.reduce((s, seg) => s + seg.days, 0);
452	  const out: TvWeeklyGoal[] = [];
453	  for (const seg of segments) {
454	    const target =
455	      daysRemaining > 0 ? ((metaMensal - committed) * seg.days) / daysRemaining : 0;
456	    const isPast = seg.to < todayIso;
457	    const isCurrent = seg.from <= todayIso && todayIso <= seg.to;
458	    const achieved = isPast || isCurrent ? sumSegment(seg) : null;
459	    out.push({ segment: seg, target, achieved, isCurrent });
460	    // Passadas comprometem o REAL (déficit/superávit redistribui);
461	    // corrente/futuras comprometem o TARGET (projeção on-target).
462	    committed += isPast ? (achieved ?? 0) : target;
463	    daysRemaining -= seg.days;
464	  }
465	  return out;
466	}
467	
468	/**
469	 * Meta semanal de UMA loja na SEMANA CORRENTE: aplica {@link weeklyTargets}
470	 * (mesma redistribuição da meta mensal usada no monthProgress da rede) ao
471	 * realizado diário da loja e extrai o segmento corrente.
472	 *
473	 * - `target` = meta redistribuída da semana corrente (semana 1 abaixo da
474	 *   meta ⇒ target sobe; acima ⇒ desce);
475	 * - `achieved` = soma do realizado nos dias do segmento corrente (segunda →
476	 *   agora — dias futuros não têm entrada no mapa e contam 0);
477	 * - `pct` = achieved/target × 100, null se target ≤ 0 (sem % honesto).
478	 *
479	 * Retorna null quando não há meta mensal positiva cadastrada ou quando
480	 * `now` está fora de qualquer segmento do mês (não acontece na prática).
481	 */
482	export function currentWeekGoal(
483	  metaMensal: number | null | undefined,
484	  realizadoPorDia: Map<string, number>,
485	  now: Date,
486	): TvStoreWeeklyGoal | null {
487	  if (metaMensal == null || metaMensal <= 0) return null;
488	  const current = weeklyTargets(metaMensal, realizadoPorDia, now).find(
489	    (w) => w.isCurrent,
490	  );
491	  if (!current) return null;
492	  const achieved = current.achieved ?? 0;
493	  return {
494	    target: current.target,
495	    achieved,
496	    pct: current.target > 0 ? (achieved / current.target) * 100 : null,
497	  };
498	}
499	
500	/**
501	 * Fração ESPERADA da semana corrente já decorrida em `now` — análoga ao
502	 * `expectedMonthPct` da barra mensal (dias inteiros; HOJE conta inteiro,
503	 * mesmo padrão de `now.getDate() / daysInMonth`). A "semana" é o segmento
504	 * seg-dom do mês CORRENTE recortado por {@link monthWeekSegments} (mesmo
505	 * recorte de {@link weeklyTargets}/{@link currentWeekGoal}).
506	 *
507	 * Uso: pace-ajustar a COR da meta semanal (`ratio = %real / %esperado`),
508	 * consistente com a barra mensal — começo de semana no ritmo NÃO fica
509	 * vermelho. O % numérico exibido segue sendo o real (achieved/target).
510	 *
511	 * Retorna 1 se `now` não cair em nenhum segmento (defensivo — na prática
512	 * todo dia do mês pertence a um segmento).
513	 */
514	export function expectedWeekFraction(now: Date): number {
515	  const todayIso = toIsoDateLocal(now);
516	  const segment = monthWeekSegments(now.getFullYear(), now.getMonth()).find(
517	    (s) => s.from <= todayIso && todayIso <= s.to,
518	  );
519	  if (!segment) return 1;
520	  // Math.round absorve a hora de DST (diferença 23h/25h em viradas)
521	  const elapsedDays =
522	    Math.round(
523	      (parseIsoDateLocal(todayIso).getTime() -
524	        parseIsoDateLocal(segment.from).getTime()) /
525	        86_400_000,
526	    ) + 1;
527	  return Math.min(1, elapsedDays / segment.days);
528	}
529	
530	// ─────────────────────────────────────────────────────────────────────────────
531	// Curva horária (R5) + projeção de fim de mês (R3)
532	// ─────────────────────────────────────────────────────────────────────────────
533	
534	/**
535	 * Hora-limite da madrugada no DIA COMERCIAL: buckets 00h–05h pertencem ao
536	 * FIM do dia, não ao começo. O caixa do Degust agrupa por dataCaixa — uma
537	 * venda às 02:00 tem dataCaixa do dia anterior (é o fechamento da noite),
538	 * então na curva horária ela vem DEPOIS das 23h, nunca antes da manhã.
539	 *
540	 * NÃO atrelar este corte a {@link TV_BUSINESS_HOURS}.start: a abertura
541	 * comercial (08h — brunch Lago Sul vende com chaves reais "08"/"09" no
542	 * byHour) é regra de meta/pró-rata; este corte só separa madrugada de
543	 * manhã na curva horária — 06h é seguro abaixo de qualquer abertura real.
544	 */
545	export const TV_OVERNIGHT_END_HOUR = 6;
546	
547	/**
548	 * Rank de uma hora-calendário dentro do DIA COMERCIAL: madrugada (00–05)
549	 * desloca +24 para ordenar DEPOIS das 23h. Sequência resultante:
550	 * 06, 07, …, 23, 24 (=00h), 25 (=01h), …, 29 (=05h).
551	 */
552	export function businessHourRank(hour: number): number {
553	  return hour < TV_OVERNIGHT_END_HOUR ? hour + 24 : hour;
554	}
555	
556	/**
557	 * Base "ontem até a MESMA hora" usando a curva horária REAL do dia de
558	 * referência: `prevDayTotal` × fração, onde fração = cumulativo de
559	 * `prevDayByHour` até HH:mm ÷ cumulativo total. A hora corrente entra com
560	 * fração linear do minuto dentro da hora (15:30 → metade do bucket "15").
561	 *
562	 * A curva é usada APENAS como fração (kits têm valorUnitario 0 na fonte) —
563	 * o valor absoluto vem sempre do total oficial `prevDayTotal`.
564	 *
565	 * O cumulativo segue a ordem do DIA COMERCIAL ({@link businessHourRank}):
566	 * buckets da madrugada (00h–05h, dataCaixa do dia anterior — fechamento da
567	 * noite) ordenam DEPOIS das 23h, e a hora corrente também é ranqueada —
568	 * às 00:30 o ponto de corte é 24,5 (fim do dia comercial corrente), não
569	 * 0,5. Sem isso, uma venda às 02h de ontem inflava a base da MANHÃ de hoje.
570	 *
571	 * Retorna null quando não há base honesta — curva ausente/vazia, cumulativo
572	 * total 0, total não positivo ou fração 0 (antes da 1ª venda do dia de
573	 * referência) — para o caller cair no fallback pró-rata linear existente.
574	 */
575	export function hourlyPaceBase(
576	  prevDayTotal: number,
577	  prevDayByHour: Record<string, number> | undefined,
578	  now: Date,
579	): number | null {
580	  if (prevDayTotal <= 0 || !prevDayByHour) return null;
581	  const buckets: Array<[number, number]> = [];
582	  for (const [hh, value] of Object.entries(prevDayByHour)) {
583	    const hour = Number(hh);
584	    if (!Number.isInteger(hour) || hour < 0 || hour > 23) continue;
585	    buckets.push([businessHourRank(hour), value]);
586	  }
587	  const cumTotal = buckets.reduce((s, [, v]) => s + v, 0);
588	  if (cumTotal <= 0) return null;
589	  const currentRank = businessHourRank(now.getHours());
590	  const minuteFraction = (now.getMinutes() + now.getSeconds() / 60) / 60;
591	  let cumNow = 0;
592	  for (const [rank, value] of buckets) {
593	    if (rank < currentRank) cumNow += value;
594	    else if (rank === currentRank) cumNow += value * minuteFraction;
595	  }
596	  if (cumNow <= 0) return null;
597	  return prevDayTotal * (cumNow / cumTotal);
598	}
599	
600	/**
601	 * Projeção de fim de mês por run-rate (mtd ÷ dias decorridos × dias do
602	 * mês), com "dias decorridos" = dias COMPLETOS decorridos + 1 (hoje conta
603	 * inteiro — sem fração de dia, decisão da spec). No dia 1º a projeção é
604	 * o run-rate de 1 dia (`mtd × diasDoMês`).
605	 */
606	export function monthEndProjection(mtdTotal: number, now: Date): number {
607	  const daysInMonth = new Date(now.getFullYear(), now.getMonth() + 1, 0).getDate();
608	  const daysElapsed = now.getDate();
609	  return (mtdTotal / daysElapsed) * daysInMonth;
610	}
611	
612	// ─────────────────────────────────────────────────────────────────────────────
613	// Pró-rata da meta
614	// ─────────────────────────────────────────────────────────────────────────────
615	
616	/**
617	 * Fração linear do dia comercial já decorrida em `now`.
618	 *
619	 * - Antes da abertura → 0 (não há venda esperada ainda).
620	 * - Depois do fechamento → 1 (meta integral esperada).
621	 * - Dentro da janela → interpolação linear simples (pró-rata).
622	 */
623	export function businessDayFraction(
624	  now: Date,
625	  hours: TvBusinessHours = TV_BUSINESS_HOURS,
626	): number {
627	  const { start, end } = hours;
628	  if (end <= start) {
629	    // Janela inválida — fail fast com comportamento seguro (sem divisão por 0)
630	    return now.getHours() >= end ? 1 : 0;
631	  }
632	  const h = now.getHours() + now.getMinutes() / 60 + now.getSeconds() / 3600;
633	  if (h <= start) return 0;
634	  if (h >= end) return 1;
635	  return (h - start) / (end - start);
636	}
637	
638	/**
639	 * % da meta pró-rata: vendido / (meta diária × fração da janela decorrida).
640	 *
641	 * Retorna null quando não dá para calcular com honestidade:
642	 * - meta ausente/zerada (sem referência), ou
643	 * - antes da janela de funcionamento (esperado = 0; divisão sem sentido).
644	 */
645	export function pctOfProRataTarget(
646	  sold: number,
647	  dailyTarget: number | null | undefined,
648	  now: Date,
649	  hours: TvBusinessHours = TV_BUSINESS_HOURS,
650	): number | null {
651	  if (dailyTarget == null || dailyTarget <= 0) return null;
652	  const fraction = businessDayFraction(now, hours);
653	  if (fraction <= 0) return null;
654	  return (sold / (dailyTarget * fraction)) * 100;
655	}
656	
657	/**
658	 * % da meta de um dia COMPLETO (sem pró-rata) — usado para canal defasado,
659	 * cujo dia de referência já encerrou.
660	 */
661	export function pctOfFullDayTarget(
662	  sold: number,
663	  dailyTarget: number | null | undefined,
664	): number | null {
665	  if (dailyTarget == null || dailyTarget <= 0) return null;
666	  return (sold / dailyTarget) * 100;
667	}
668	
669	// ─────────────────────────────────────────────────────────────────────────────
670	// Deltas comparativos (genéricos: vendas, perdas, compras — qualquer base)
671	// ─────────────────────────────────────────────────────────────────────────────
672	
673	/**
674	 * Delta % de `current` vs uma base de referência qualquer (ontem, semana
675	 * passada, período anterior do filtro…). Retorna null quando a base é
676	 * ausente ou não positiva — sem base honesta, sem número inventado.
677	 */
678	export function relativeDelta(
679	  current: number,
680	  base: number | null | undefined,
681	): number | null {
682	  if (base == null || base <= 0) return null;
683	  return ((current - base) / base) * 100;
684	}
685	
686	/**
687	 * Delta % vs MESMO DIA da semana anterior — caso particular de
688	 * {@link relativeDelta}, mantido pelo nome de domínio (comparativo
689	 * SECUNDÁRIO desde a v3; o principal é vs dia anterior).
690	 */
691	export function weekOverWeekDelta(
692	  current: number,
693	  lastWeek: number | null | undefined,
694	): number | null {
695	  return relativeDelta(current, lastWeek);
696	}
697	
698	/**
699	 * Base PRÓ-RATEADA de QUALQUER dia de referência para deltas do canal LIVE:
700	 * `referenceDayTotal × businessDayFraction(now)` — o delta resultante compara
701	 * hoje (dia parcial) vs o MESMO PONTO do dia de referência (ontem, semana
702	 * passada…), assumindo distribuição intra-dia linear na janela (mesma fração
703	 * usada no pró-rata da meta, por consistência).
704	 *
705	 * Comparar dia parcial com dia completo inflava a queda de manhã.
706	 * Canal defasado (dia completo vs dia completo) NÃO usa esta função.
707	 *
708	 * Retorna null quando a base é ausente/não positiva ou antes da abertura
709	 * (fração 0 — não há ponto de comparação honesto).
710	 */
711	export function proRataDayBase(
712	  referenceDayTotal: number | null | undefined,
713	  now: Date,
714	  hours: TvBusinessHours = TV_BUSINESS_HOURS,
715	): number | null {
716	  if (referenceDayTotal == null || referenceDayTotal <= 0) return null;
717	  const fraction = businessDayFraction(now, hours);
718	  if (fraction <= 0) return null;
719	  return referenceDayTotal * fraction;
720	}
721	
722	/**
723	 * Alias histórico de {@link proRataDayBase} com o dia de referência fixado
724	 * em "mesmo dia da semana passada" (nome da v1/v2 — mantido para não quebrar
725	 * a API existente).
726	 */
727	export function proRataLastWeekBase(
728	  lastWeek: number | null | undefined,
729	  now: Date,
730	  hours: TvBusinessHours = TV_BUSINESS_HOURS,
731	): number | null {
732	  return proRataDayBase(lastWeek, now, hours);
733	}
