735	// ─────────────────────────────────────────────────────────────────────────────
736	// RAG da loja
737	// ─────────────────────────────────────────────────────────────────────────────
738	
739	/** Entrada da classificação RAG de uma unidade. */
740	export interface StoreRagInput {
741	  /** Itens zerados em alerta (quantidade ≤ 0 com mínimo definido). */
742	  stockOutCount: number;
743	  /** Itens abaixo do mínimo (quantidade entre 0 exclusivo e o mínimo). */
744	  stockLowCount: number;
745	  /** % da meta pró-rata (apenas canal live; null = não avaliar). */
746	  pctMetaProRata: number | null;
747	  /** true quando a unidade tem venda ao vivo (canal Degust). */
748	  isLiveChannel: boolean;
749	  /** Última movimentação de estoque (ISO/Date), ou null se nenhuma hoje. */
750	  lastMovementAt: Date | string | null;
751	  /** Instante da avaliação. */
752	  now: Date;
753	  /** Janela de funcionamento (default lojas; fábrica usa TV_FACTORY_HOURS). */
754	  hours?: TvBusinessHours;
755	  /** Threshold de horas sem movimentação (default lojas 3h; fábrica 2h). */
756	  noMovementThresholdHours?: number;
757	}
758	
759	/**
760	 * Horas sem movimentação consideradas DENTRO da janela de funcionamento.
761	 *
762	 * - Fora da janela (antes de abrir / depois de fechar) retorna null —
763	 *   não faz sentido alertar madrugada sem bipagem.
764	 * - A referência é clampada ao início da janela de hoje: se a última
765	 *   movimentação foi ontem, o "relógio" só começa a contar na abertura.
766	 */
767	export function hoursWithoutMovementInWindow(
768	  lastMovementAt: Date | string | null,
769	  now: Date,
770	  hours: TvBusinessHours = TV_BUSINESS_HOURS,
771	): number | null {
772	  const fraction = businessDayFraction(now, hours);
773	  if (fraction <= 0 || fraction >= 1) return null;
774	  const windowStart = new Date(now);
775	  windowStart.setHours(hours.start, 0, 0, 0);
776	  const last = lastMovementAt
777	    ? new Date(lastMovementAt).getTime()
778	    : Number.NEGATIVE_INFINITY;
779	  const ref = Math.max(last, windowStart.getTime());
780	  return (now.getTime() - ref) / 3_600_000;
781	}
782	
783	/**
784	 * Classificação RAG de uma unidade (management-by-exception).
785	 *
786	 * Regras (design.md §1.6, ordem de precedência):
787	 * - VERMELHO: SOMENTE ruptura — item zerado em alerta (`stockOutCount > 0`).
788	 *   Venda fraca NUNCA derruba o card pra vermelho (era falso-positivo de
789	 *   manhã, quando o pró-rata ainda é instável).
790	 * - ÂMBAR: itens abaixo do mínimo (`stockLowCount > 0`) OU unidade sem
791	 *   movimentação há mais que o threshold dentro da janela OU venda live com
792	 *   ratio pró-rata abaixo de {@link LIVE_SALES_AMBER_THRESHOLD_PCT}% —
793	 *   esta última SOMENTE a partir de {@link LIVE_SALES_AMBER_FROM_HOUR}h,
794	 *   em canal live e com meta cadastrada (pct != null).
795	 * - OK: nenhum desvio — tela calma, sem cor.
796	 */
797	export function classifyStoreRag(input: StoreRagInput): {
798	  status: TvRagStatus;
799	  reasons: string[];
800	} {
801	  const hours = input.hours ?? TV_BUSINESS_HOURS;
802	  const noMovementThreshold =
803	    input.noMovementThresholdHours ?? NO_MOVEMENT_THRESHOLD_HOURS;
804	  const reasons: string[] = [];
805	
806	  // ── Vermelho: só ruptura (item zerado em alerta) ──
807	  if (input.stockOutCount > 0) {
808	    reasons.push(
809	      `${input.stockOutCount} ${input.stockOutCount === 1 ? 'item zerado' : 'itens zerados'} em alerta`,
810	    );
811	    return { status: 'red', reasons };
812	  }
813	
814	  // ── Âmbar ──
815	  if (input.stockLowCount > 0) {
816	    reasons.push(
817	      `${input.stockLowCount} ${input.stockLowCount === 1 ? 'item abaixo' : 'itens abaixo'} do mínimo`,
818	    );
819	  }
820	  const gapHours = hoursWithoutMovementInWindow(
821	    input.lastMovementAt,
822	    input.now,
823	    hours,
824	  );
825	  if (gapHours !== null && gapHours > noMovementThreshold) {
826	    reasons.push(`sem movimentação há ${Math.floor(gapHours)}h`);
827	  }
828	  if (
829	    input.isLiveChannel &&
830	    input.pctMetaProRata !== null &&
831	    input.pctMetaProRata < LIVE_SALES_AMBER_THRESHOLD_PCT &&
832	    input.now.getHours() >= LIVE_SALES_AMBER_FROM_HOUR
833	  ) {
834	    reasons.push(
835	      `venda ao vivo em ${Math.round(input.pctMetaProRata)}% do esperado pró-rata`,
836	    );
837	  }
838	  if (reasons.length > 0) return { status: 'amber', reasons };
839	
840	  return { status: 'ok', reasons: [] };
841	}
842	
843	/** Entrada de {@link buildNoMovementException}. */
844	export interface NoMovementExceptionInput {
845	  lojaId: number;
846	  lojaNome: string;
847	  /** Timestamp da última movimentação (ISO/Date), ou null se nenhuma hoje. */
848	  lastMovementAt: Date | string | null;
849	  now: Date;
850	  /** Janela de funcionamento (default lojas; fábrica usa TV_FACTORY_HOURS). */
851	  hours?: TvBusinessHours;
852	  /** Threshold em horas (default lojas 3h; fábrica 2h). */
853	  thresholdHours?: number;
854	}
855	
856	/**
857	 * Exceção "sem movimentação" derivada DIRETO do dado estruturado (timestamp
858	 * da última bipagem + janela), nunca por parsing de string de ragReasons —
859	 * por isso INDEPENDE da cor do card (aparece mesmo com card vermelho) e
860	 * cobre também a fábrica (janela/threshold próprios via parâmetros).
861	 * Retorna null quando não há gap acima do threshold dentro da janela.
862	 */
863	export function buildNoMovementException(
864	  input: NoMovementExceptionInput,
865	): TvException | null {
866	  const threshold = input.thresholdHours ?? NO_MOVEMENT_THRESHOLD_HOURS;
867	  const gap = hoursWithoutMovementInWindow(
868	    input.lastMovementAt,
869	    input.now,
870	    input.hours ?? TV_BUSINESS_HOURS,
871	  );
872	  if (gap === null || gap <= threshold) return null;
873	  return {
874	    id: `no-movement:${input.lojaId}`,
875	    kind: 'no-movement',
876	    severity: 'amber',
877	    lojaId: input.lojaId,
878	    lojaNome: input.lojaNome,
879	    message: `${input.lojaNome} sem movimentação há ${Math.floor(gap)}h em horário comercial`,
880	  };
881	}
