883	// ─────────────────────────────────────────────────────────────────────────────
884	// Formatação compacta de moeda (tipografia de TV: "R$ 12,4k")
885	// ─────────────────────────────────────────────────────────────────────────────
886	
887	function trimOneDecimal(v: number): string {
888	  const rounded = Math.round(v * 10) / 10;
889	  return rounded.toLocaleString('pt-BR', {
890	    minimumFractionDigits: 0,
891	    maximumFractionDigits: 1,
892	  });
893	}
894	
895	/**
896	 * Formata um valor em BRL compacto para leitura a 3-5 metros:
897	 * 950 → "R$ 950" · 12.400 → "R$ 12,4k" · 1.250.000 → "R$ 1,3M".
898	 * Valores negativos preservam o sinal ("-R$ 1,2k").
899	 */
900	export function formatCompactBRL(value: number): string {
901	  const sign = value < 0 ? '-' : '';
902	  const abs = Math.abs(value);
903	  // Bump pra M quando o arredondamento em k chegaria a 1000k
904	  if (abs >= 1_000_000 || (abs >= 1_000 && Math.round(abs / 100) >= 10_000)) {
905	    return `${sign}R$ ${trimOneDecimal(abs / 1_000_000)}M`;
906	  }
907	  if (abs >= 1_000) {
908	    return `${sign}R$ ${trimOneDecimal(abs / 1_000)}k`;
909	  }
910	  return `${sign}R$ ${Math.round(abs).toLocaleString('pt-BR')}`;
911	}
912	
913	// ─────────────────────────────────────────────────────────────────────────────
914	// Staleness
915	// ─────────────────────────────────────────────────────────────────────────────
916	
917	/**
918	 * Classifica o frescor de um dado-fonte dado o intervalo esperado:
919	 * - `fresh`: idade abaixo de 2× o intervalo esperado (tolera um ciclo perdido).
920	 * - `stale`: idade entre 2× e 6× (âmbar na UI, conforme spec).
921	 * - `very-stale`: idade a partir de 6×, timestamp inválido ou ausente.
922	 */
923	export function classifyStaleness(
924	  lastUpdatedAt: Date | string | number | null | undefined,
925	  expectedIntervalMs: number,
926	  now: Date,
927	): TvFreshnessLevel {
928	  if (lastUpdatedAt == null) return 'very-stale';
929	  const ts = new Date(lastUpdatedAt).getTime();
930	  if (!Number.isFinite(ts) || ts <= 0) return 'very-stale';
931	  const age = now.getTime() - ts;
932	  if (age < 2 * expectedIntervalMs) return 'fresh';
933	  if (age < 6 * expectedIntervalMs) return 'stale';
934	  return 'very-stale';
935	}
936	
937	/**
938	 * Monta o freshness consolidado a partir dos timestamps CRUS de última
939	 * atualização bem-sucedida (React Query `dataUpdatedAt`, em ms; 0 = nunca).
940	 *
941	 * A classificação depende de `now`: o chamador DEVE reavaliar com um relógio
942	 * que AVANÇA (tick de minuto), para que um outage total — nenhuma query
943	 * devolvendo dado novo — escale o chip pra âmbar quando `dataUpdatedAt`
944	 * parar de avançar além de 2× o intervalo esperado.
945	 */
946	export function buildFreshness(
947	  liveUpdatedAtMs: number,
948	  stockUpdatedAtMs: number,
949	  intervals: { liveMs: number; slowMs: number },
950	  now: Date,
951	): TvFreshness {
952	  const liveUpdatedAt =
953	    liveUpdatedAtMs > 0 ? new Date(liveUpdatedAtMs).toISOString() : null;
954	  const stockUpdatedAt =
955	    stockUpdatedAtMs > 0 ? new Date(stockUpdatedAtMs).toISOString() : null;
956	  return {
957	    vendasLive: {
958	      updatedAt: liveUpdatedAt,
959	      level: classifyStaleness(liveUpdatedAt, intervals.liveMs, now),
960	      expectedIntervalMs: intervals.liveMs,
961	    },
962	    estoque: {
963	      updatedAt: stockUpdatedAt,
964	      level: classifyStaleness(stockUpdatedAt, intervals.slowMs, now),
965	      expectedIntervalMs: intervals.slowMs,
966	    },
967	    geradoEm: now.toISOString(),
968	  };
969	}
970	
971	/**
972	 * Detecta flash live defasado de UMA loja: caixa aberto mas a última
973	 * atualização do POS (lastUpdate) está há mais de thresholdMinutes,
974	 * DENTRO da janela comercial. Fora da janela ou caixa fechado/sem
975	 * timestamp → false (defasagem noturna é esperada).
976	 */
977	export function detectStaleLiveFlash(params: {
978	  caixaAberto: boolean | null;
979	  lastUpdate: Date | null;
980	  now: Date;
981	  /** Minutos sem atualização que caracterizam PDV dessincronizado. Default: TV_FLASH_STALE_MINUTES. */
982	  thresholdMinutes?: number;
983	  /** Janela comercial para avaliação. Default: TV_BUSINESS_HOURS. */
984	  hours?: TvBusinessHours;
985	}): boolean {
986	  const { caixaAberto, lastUpdate, now } = params;
987	  const thresholdMinutes = params.thresholdMinutes ?? TV_FLASH_STALE_MINUTES;
988	  const hours = params.hours ?? TV_BUSINESS_HOURS;
989	
990	  if (!caixaAberto || !lastUpdate) return false;
991	
992	  // Só sinaliza dentro da janela comercial (fora = defasagem noturna esperada)
993	  const fraction = businessDayFraction(now, hours);
994	  if (fraction <= 0 || fraction >= 1) return false;
995	
996	  const ageMinutes = (now.getTime() - lastUpdate.getTime()) / 60_000;
997	  return ageMinutes > thresholdMinutes;
