1004	const SEVERITY_ORDER: Record<string, number> = { red: 0, amber: 1 };
1005	// design.md §6.1: rupturas → abaixo-do-mínimo → sem-bipagem → stale
1006	const KIND_ORDER: Record<string, number> = {
1007	  'stock-out': 0,
1008	  'stock-low': 1,
1009	  'no-movement': 2,
1010	  'stale-data': 3,
1011	};
