1013	/**
1014	 * Ordena exceções por severidade (vermelho antes de âmbar), depois por tipo
1015	 * (falta total, abaixo do mínimo, sem movimentação, dado stale — nesta ordem,
1016	 * design.md §6.1) e por mensagem (estável), limitando a `limit` linhas com
1017	 * contagem do excedente.
1018	 */
1019	export function sortAndLimitExceptions(
1020	  exceptions: TvException[],
1021	  limit: number = TV_EXCEPTIONS_LIMIT,
1022	): TvExceptionsResult {
1023	  const sorted = [...exceptions].sort((a, b) => {
1024	    const sev = (SEVERITY_ORDER[a.severity] ?? 9) - (SEVERITY_ORDER[b.severity] ?? 9);
1025	    if (sev !== 0) return sev;
1026	    const kind = (KIND_ORDER[a.kind] ?? 9) - (KIND_ORDER[b.kind] ?? 9);
1027	    if (kind !== 0) return kind;
1028	    return a.message.localeCompare(b.message, 'pt-BR');
1029	  });
1030	  return {
1031	    items: sorted.slice(0, limit),
1032	    overflowCount: Math.max(0, sorted.length - limit),
1033	    totalCount: sorted.length,
1034	  };
1035	}
