1122	/**
1123	 * Classifica linhas de estoque em alertas por loja (apenas produtos ATIVOS
1124	 * devem chegar aqui — o JOIN com `produtos_master.ativo = true` é feito na
1125	 * query). Regras (critério existente do projeto, sem schema novo):
1126	 * - SÓ setor {@link TV_ALERT_SETOR} entra em alerta (regra do CTO
1127	 *   2026-06-05: alertas só do setor de produtos vendáveis) — comparação
1128	 *   normalizada client-side porque a caixa no banco é inconsistente;
1129	 * - zerado (vermelho): quantidade ≤ 0 com mínimo definido (positivo);
1130	 * - abaixo do mínimo (âmbar): quantidade entre 0 exclusivo e o mínimo.
1131	 */
1132	export function buildStockSummary(rows: StockRow[]): Map<number, StockDetail> {
1133	  const out = new Map<number, StockDetail>();
1134	  for (const row of rows) {
1135	    if (row.loja_id == null) continue;
1136	    if (!isTvAlertSetor(row.setor)) continue; // fora do setor vendável → sem alerta
1137	    const min = row.quantidade_minima ?? 0;
1138	    if (min <= 0) continue; // sem mínimo definido → sem alerta
1139	    const qty = row.quantidade_atual ?? 0;
1140	    if (qty >= min) continue; // dentro do normal
1141	    let detail = out.get(row.loja_id);
1142	    if (!detail) {
1143	      detail = { zerados: 0, abaixoMinimo: 0, itens: [] };
1144	      out.set(row.loja_id, detail);
1145	    }
1146	    const zerado = qty <= 0;
1147	    if (zerado) detail.zerados += 1;
1148	    else detail.abaixoMinimo += 1;
1149	    detail.itens.push({
1150	      produtoNome: row.produtoNome,
1151	      quantidade: qty,
1152	      quantidadeMinima: min,
1153	      zerado,
1154	    });
1155	  }
1156	  return out;
