1170	    for (const item of detail.itens) {
1171	      out.push({
1172	        id: `${item.zerado ? 'stock-out' : 'stock-low'}:${lojaId}:${item.produtoNome}`,
1173	        kind: item.zerado ? 'stock-out' : 'stock-low',
1174	        severity: item.zerado ? 'red' : 'amber',
1175	        lojaId,
1176	        lojaNome,
1177	        message: item.zerado
1178	          ? `${item.produtoNome} zerado — ${lojaNome}`
1179	          : `${item.produtoNome} abaixo do mínimo (${item.quantidade}/${item.quantidadeMinima}) — ${lojaNome}`,
1180	        produtoNome: item.produtoNome,
1181	        quantidade: item.quantidade,
