1200	/**
1201	 * Corrige o `loja_id` das linhas de flash-vendas.
1202	 *
1203	 * LANDMINE conhecida: a edge function `degust-pos-financial` (deployada)
1204	 * só mapeia os códigos Degust 1→4 e 2→5; códigos não mapeados passam CRUS
1205	 * (ex.: BSB Shopping = código Degust 3 chega como `loja_id: 3`, colidindo
1206	 * com Asa Norte). Aqui remapeamos usando a tabela `degust_stores`
1207	 * (degust_loja_codigo → loja_id), que é a fonte de verdade em runtime.
1208	 *
1209	 * - Linha cujo loja_id já é uma loja Degust conhecida → mantém.
1210	 * - Linha cujo loja_id corresponde a um código Degust → remapeia.
1211	 * - Caso contrário → descarta (não corromper outra loja).
1212	 */
1213	export function remapFlashLojaIds(
1214	  rows: FlashRow[],
1215	  degustCodeToLoja: ReadonlyMap<number, number>,
1216	  knownDegustLojaIds: ReadonlySet<number>,
1217	): FlashRow[] {
1218	  const out: FlashRow[] = [];
1219	  for (const row of rows) {
1220	    if (knownDegustLojaIds.has(row.loja_id)) {
1221	      out.push(row);
1222	      continue;
1223	    }
1224	    const mapped = degustCodeToLoja.get(row.loja_id);
1225	    if (mapped != null) {
1226	      out.push({ ...row, loja_id: mapped });
1227	    }
1228	    // não mapeável → descartado de propósito (ver TSDoc)
1229	  }
1230	  return out;
