1233	/**
1234	 * Converte os itens de alerta de uma unidade em estoque crítico NOMEADO,
1235	 * ordenado por severidade: zerados (⛔) primeiro, depois abaixo do mínimo
1236	 * (⚠) por % FALTANTE decrescente ((minima − quantidade) / minima); empate
1237	 * por nome (estável). Dentro dos zerados, quantidade mais negativa primeiro
1238	 * (mesma fração). A coluna exibe os {@link TV_CRITICAL_TOP_N} primeiros;
1239	 * o drill-down, a lista completa.
1240	 */
1241	export function sortCriticalItems(items: TvStockAlertItem[]): TvCriticalItem[] {
1242	  const missingFraction = (c: TvCriticalItem): number =>
1243	    c.minima > 0 ? (c.minima - c.quantidade) / c.minima : 0;
1244	  return items
1245	    .map<TvCriticalItem>((i) => ({
1246	      nome: i.produtoNome,
1247	      quantidade: i.quantidade,
1248	      minima: i.quantidadeMinima,
1249	      severity: i.zerado ? 'zerado' : 'abaixo-minimo',
1250	    }))
1251	    .sort((a, b) => {
1252	      if (a.severity !== b.severity) return a.severity === 'zerado' ? -1 : 1;
1253	      const diff = missingFraction(b) - missingFraction(a);
1254	      if (diff !== 0) return diff;
1255	      return a.nome.localeCompare(b.nome, 'pt-BR');
1256	    });
1257	}
