1391	
1392	/** Página de resultado mínima consumida por {@link fetchAllPages}. */
1393	export interface TvPageResult<T> {
1394	  data: T[] | null;
1395	  error: { message: string } | null;
1396	}
1397	
1398	/**
1399	 * Busca TODAS as linhas paginando com `.range()`: o PostgREST corta qualquer
1400	 * resposta em 1000 linhas mesmo com `.limit()` maior — truncamento SILENCIOSO
1401	 * (mesmo padrão de `features/producao/hooks/useProductionForecast`).
1402	 *
1403	 * Loop até a página vir menor que `pageSize`. O fetcher é injetado (esta
1404	 * função não faz I/O próprio — testável com mock) e DEVE aplicar ordenação
1405	 * estável (`.order` em coluna única, ex.: `id`) para as páginas não se
1406	 * sobreporem entre requests.
1407	 */
1408	export async function fetchAllPages<T>(
1409	  fetchPage: (from: number, to: number) => PromiseLike<TvPageResult<T>>,
1410	  pageSize = 1000,
1411	): Promise<T[]> {
1412	  const all: T[] = [];
1413	  let offset = 0;
1414	  for (;;) {
1415	    const { data, error } = await fetchPage(offset, offset + pageSize - 1);
1416	    if (error) throw error;
1417	    const rows = data ?? [];
1418	    all.push(...rows);
1419	    if (rows.length < pageSize) return all;
1420	    offset += pageSize;
1421	  }
1422	}
