195	/**
196	 * Linha SECUNDÁRIA de meta semanal do card: label "SEMANA" + % em destaque
197	 * (cor pace-adjusted pela mesma régua da diária/mensal; emerald quando
198	 * ≥ 100%) + valores exatos "R$ X / R$ Y" + mini barra de progresso
199	 * ({@link TvMetaBar} mini com tick dourado no esperado-agora da semana).
200	 *
201	 * COR pace-adjusted: ratio = %real / %esperado-agora, com esperado =
202	 * dias decorridos ÷ dias do segmento seg-dom corrente do mês
203	 * ({@link expectedWeekFraction} — derivado localmente porque o
204	 * `weeklyGoal` do model não expõe o segmento). Começo de semana no ritmo
205	 * NÃO fica vermelho. O % NUMÉRICO exibido segue sendo o real.
206	 */
207	function TvStoreWeeklyGoalLine({
208	  weeklyGoal,
209	  now,
210	}: {
211	  weeklyGoal: NonNullable<TvStoreData['weeklyGoal']>;
212	  now: Date;
213	}) {
214	  const { target, achieved, pct } = weeklyGoal;
215	  const beaten = pct != null && pct >= 100;
216	  const expectedWeekPct = Math.round(expectedWeekFraction(now) * 100);
217	  const barColor: TvBarColor = beaten
218	    ? 'sage'
219	    : metaBarColorFromRatio(
220	        pct != null && expectedWeekPct > 0 ? pct / expectedWeekPct : null,
221	        now,
222	      );
223	  const pctCls = beaten ? 'text-emerald-600' : WEEKLY_PCT_CLS[barColor];
224	
225	  return (
226	    <div className="mt-2" data-testid="tv-weekly-goal">
227	      <div className="flex flex-wrap items-baseline justify-between gap-x-2 gap-y-0.5">
228	        <span className="font-momma text-[10px] font-semibold uppercase tracking-wider text-[#7C887E]">
229	          SEMANA
230	        </span>
231	        {/* Sem truncate: valor exato nunca pode ser cortado — quebra linha */}
232	        <span className="min-w-0 text-right font-momma text-[10px] tabular-nums text-[#9ca3af]">
233	          <span
234	            className={`text-xs font-bold tabular-nums ${pctCls}`}
235	            data-testid="tv-weekly-goal-pct"
236	          >
237	            {pct != null ? `${Math.round(pct)}%` : '—'}
238	          </span>{' '}
239	          {formatExactBRL(achieved)} / {formatExactBRL(target)}
240	        </span>
241	      </div>
242	      <div className="mt-1">
243	        <TvMetaBar
244	          fillPct={pct}
245	          expectedPct={pct != null ? expectedWeekPct : null}
246	          color={barColor}
247	          size="mini"
248	        />
249	      </div>
250	    </div>
251	  );
252	}
